/* Twitter Theme — Tailwind v3 (rgb) */
/* Channel triplets — consume via rgb(var(--token)). See tailwind.config snippet in docs. */

@layer base {
  /* Twitter Theme - Auto-generated from tweakcn */

  /* Light mode (:root) */
  :root {
    --background: 255 255 255;
    --foreground: 16 20 24;
    --card: 248 248 248;
    --card-foreground: 16 20 24;
    --popover: 255 255 255;
    --popover-foreground: 16 20 24;
    --primary: 30 156 240;
    --primary-foreground: 255 255 255;
    --secondary: 16 20 24;
    --secondary-foreground: 255 255 255;
    --muted: 228 228 228;
    --muted-foreground: 16 20 24;
    --accent: 226 236 249;
    --accent-foreground: 30 156 240;
    --destructive: 245 30 45;
    --destructive-foreground: 255 255 255;
    --border: 226 233 237;
    --input: 248 248 248;
    --ring: 24 160 242;
    --chart-1: 30 156 240;
    --chart-2: 0 184 122;
    --chart-3: 247 185 39;
    --chart-4: 32 192 101;
    --chart-5: 224 33 93;
    --radius: 1.3rem;
    --sidebar: 248 248 248;
    --sidebar-foreground: 16 20 24;
    --sidebar-primary: 30 156 240;
    --sidebar-primary-foreground: 255 255 255;
    --sidebar-accent: 226 236 249;
    --sidebar-accent-foreground: 30 156 240;
    --sidebar-border: 226 233 238;
    --sidebar-ring: 24 160 242;
    --font-sans: Open Sans, sans-serif;
    --font-serif: Georgia, serif;
    --font-mono: Menlo, monospace;
    --shadow-color: 29 161 242;
    --shadow-opacity: 0;
    --shadow-blur: 0px;
    --shadow-spread: 0px;
    --shadow-offset-x: 0px;
    --shadow-offset-y: 2px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0);
    --shadow-xs: 0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0);
    --shadow-sm:
      0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
      0px 1px 2px -1px hsl(202.82 89.12% 53.14% / 0);
    --shadow:
      0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
      0px 1px 2px -1px hsl(202.82 89.12% 53.14% / 0);
    --shadow-md:
      0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
      0px 2px 4px -1px hsl(202.82 89.12% 53.14% / 0);
    --shadow-lg:
      0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
      0px 4px 6px -1px hsl(202.82 89.12% 53.14% / 0);
    --shadow-xl:
      0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
      0px 8px 10px -1px hsl(202.82 89.12% 53.14% / 0);
    --shadow-2xl: 0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0);
    --tracking-normal: 0em;
  }

  /* Dark mode (.dark) */
  .dark {
    --background: 0 0 0;
    --foreground: 232 232 232;
    --card: 23 24 29;
    --card-foreground: 219 219 219;
    --popover: 0 0 0;
    --popover-foreground: 232 232 232;
    --primary: 30 156 240;
    --primary-foreground: 255 255 255;
    --secondary: 242 242 242;
    --secondary-foreground: 16 20 24;
    --muted: 24 24 24;
    --muted-foreground: 112 117 122;
    --accent: 7 21 32;
    --accent-foreground: 30 156 240;
    --destructive: 245 30 45;
    --destructive-foreground: 255 255 255;
    --border: 38 38 38;
    --input: 33 48 60;
    --ring: 24 160 242;
    --chart-1: 30 156 240;
    --chart-2: 0 184 122;
    --chart-3: 247 185 39;
    --chart-4: 32 192 101;
    --chart-5: 224 33 93;
    --radius: 1.3rem;
    --sidebar: 23 24 29;
    --sidebar-foreground: 219 219 219;
    --sidebar-primary: 24 160 242;
    --sidebar-primary-foreground: 255 255 255;
    --sidebar-accent: 7 21 32;
    --sidebar-accent-foreground: 30 156 240;
    --sidebar-border: 57 68 76;
    --sidebar-ring: 24 160 242;
    --font-sans: Open Sans, sans-serif;
    --font-serif: Georgia, serif;
    --font-mono: Menlo, monospace;
    --shadow-color: 29 161 242;
    --shadow-opacity: 0;
    --shadow-blur: 0px;
    --shadow-spread: 0px;
    --shadow-offset-x: 0px;
    --shadow-offset-y: 2px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0);
    --shadow-xs: 0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0);
    --shadow-sm:
      0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
      0px 1px 2px -1px hsl(202.82 89.12% 53.14% / 0);
    --shadow:
      0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
      0px 1px 2px -1px hsl(202.82 89.12% 53.14% / 0);
    --shadow-md:
      0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
      0px 2px 4px -1px hsl(202.82 89.12% 53.14% / 0);
    --shadow-lg:
      0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
      0px 4px 6px -1px hsl(202.82 89.12% 53.14% / 0);
    --shadow-xl:
      0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0),
      0px 8px 10px -1px hsl(202.82 89.12% 53.14% / 0);
    --shadow-2xl: 0px 2px 0px 0px hsl(202.82 89.12% 53.14% / 0);
  }

}
